package io.github.finalparadox.item;
import net.minecraft.sounds.*;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.Ingredient;
public enum VoidArmorMaterial implements ArmorMaterial{INSTANCE;@Override public int getDurabilityForType(ArmorItem.Type t){return switch(t){case BOOTS->481;case LEGGINGS->555;case CHESTPLATE->592;case HELMET->407;};}@Override public int getDefenseForType(ArmorItem.Type t){return switch(t){case BOOTS->3;case LEGGINGS->6;case CHESTPLATE->8;case HELMET->3;};}@Override public int getEnchantmentValue(){return 15;}@Override public SoundEvent getEquipSound(){return SoundEvents.ARMOR_EQUIP_NETHERITE;}@Override public Ingredient getRepairIngredient(){return Ingredient.of(Items.NETHERITE_INGOT);}@Override public String getName(){return "finalparadox:void_armor";}@Override public float getToughness(){return 3;}@Override public float getKnockbackResistance(){return .1F;}}
